test('logical mappings preserve parents and selected context, purpose and public redaction',async({page})=>{
 const errors:string[]=[];page.on('pageerror',e=>errors.push(e.message));
 const brief={format:'diagramcloud.project-brief',version:1,project:{id:'navigation-context',title:'Synthetic navigation context'},scope:[{id:'work',title:'Declared workstream',kind:'workstream',repositoryIds:['app']},{id:'task',title:'Selected task',kind:'task',parentId:'work'}],repositories:[{id:'app',title:'Synthetic implementation',host:'local',locator:'app',revision:'a'.repeat(40)},{id:'other',title:'Unbound implementation',host:'local',locator:'other',revision:'b'.repeat(40)}]};
 await page.goto('/');await page.locator('.header-actions').getByRole('button',{name:'New analysis',exact:true}).click();await page.getByRole('radio',{name:/Hybrid/}).check();await page.getByLabel('Analysis purpose',{exact:true}).selectOption('education');await page.getByLabel('Project brief JSON',{exact:true}).fill(JSON.stringify(brief));await page.getByRole('button',{name:'Preview project',exact:true}).click();await page.getByRole('button',{name:'Apply imported document',exact:true}).click();await expect(page.getByText('Saved locally',{exact:true})).toBeVisible();await expect(page.getByLabel('Recipe and pattern workbench').getByLabel('View purpose',{exact:true})).toHaveValue('education');
 const nav=page.getByTestId('project-navigator');await nav.getByRole('tab',{name:'Mappings',exact:true}).click();await expect(nav).toContainText('Explicit experience relation');await expect(nav).toContainText('project-brief-source');await expect(nav).not.toContainText('Unbound implementation');await nav.getByRole('button',{name:'Declared workstream',exact:true}).click();await expect(page.getByTestId('view-brief-overview')).toBeVisible();await expect(page.getByTestId('view-brief-children-work')).toBeVisible();
 await page.getByRole('button',{name:'Details panel',exact:true}).click();const context=page.getByTestId('project-context');await expect(context).toContainText('Selection: Declared workstream');await expect(context).toContainText('brief-scope-work');await context.getByRole('tab',{name:'Alternatives',exact:true}).click();await expect(context).toContainText('Code');await expect(context).toContainText('unsupported');await context.getByRole('tab',{name:'Evidence',exact:true}).click();await expect(context).toContainText('Author-supplied ProjectBrief');await context.getByText('Manual assistance',{exact:true}).click();const downloading=page.waitForEvent('download');await context.getByRole('button',{name:'Download context',exact:true}).click();const file=await downloading;await file.saveAs('test-results/selected-navigation-context.json');const selected=JSON.parse(readFileSync('test-results/selected-navigation-context.json','utf8'));expect(selected.selection.nodeId).toBe('brief-scope-work');expect(selected.components).toHaveLength(1);expect(selected.assets.requirements).toHaveLength(1);expect(selected.assets.requirements[0].nodeId).toBe('brief-scope-work');
 await nav.getByLabel('Navigation filter',{exact:true}).fill('Selected task');await expect(nav.getByRole('status')).toContainText('remains selected outside this filter');await context.getByRole('tab',{name:'Details',exact:true}).click();await expect(context).toContainText('Selection: Declared workstream');await nav.getByRole('tab',{name:'Views',exact:true}).click();await nav.getByLabel('Navigation filter',{exact:true}).fill('author-declared structure');await expect(nav.getByRole('heading',{name:'System',exact:true})).toBeVisible();await expect(nav.getByRole('button',{name:'Inside Declared workstream',exact:true})).toBeVisible();
 await page.setViewportSize({width:390,height:844});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await context.screenshot({path:'test-results/selected-context-narrow.png'});
 await page.getByRole('tab',{name:'Portfolio',exact:true}).click();await expect(context).not.toContainText('brief-scope-work');await expect(nav).not.toContainText('brief-scope-work');await expect(context).not.toContainText('Declared workstream');expect(errors).toEqual([]);
});

const relationshipPrivate='SYNTHETIC_PRIVATE_RELATION_SENTINEL';
function relationshipProject(id:string){
 const edges=Array.from({length:53},(_,i)=>({id:`connection-${String(i).padStart(2,'0')}`,source:'left',target:'right',label:`Synthetic connection ${i}`,kind:(['query','control','dependency','stream','batch'] as const)[i%5],...(i%4===3?{}:{basis:(['planned','static-source','unknown'] as const)[i%4]}),...(i===0?{quantity:{value:0,unit:'events/day',provenance:'synthetic' as const,note:'Illustrative zero, not a measurement'}}:{})}));
 return validateDocument(documentSchema.parse({schemaVersion:1,id,title:'Synthetic complete relationship table',rootViewId:'root',summary:'Synthetic supplied connections, no execution claims.',nodes:[
 {id:'parent',label:'Synthetic relation parent',childViewId:'child'},
 {id:'left',label:'Synthetic endpoint A',sourceIds:['context-source']},{id:'right',label:'Synthetic endpoint B'},
 {id:'code',label:'Synthetic retained code'},
 {id:'private',label:relationshipPrivate,visibility:'private',sourceIds:['private-source']}],
 edges:[...edges,{id:'private-connection',source:'left',target:'private',label:relationshipPrivate,visibility:'private'},{id:'unplaced-connection',source:'left',target:'right',label:'Synthetic unplaced connection'}],
 views:[{id:'root',title:'Synthetic relation parent view',nodeIds:['parent','left','right','private'],edgeIds:[...edges.map(e=>e.id),'private-connection'],positions:{parent:{x:0,y:0},left:{x:300,y:0},right:{x:600,y:0},private:{x:900,y:0}}},
 {id:'child',title:'Synthetic retained detail',nodeIds:['code','right'],positions:{code:{x:0,y:0},right:{x:300,y:0}}},
 ...Array.from({length:7},(_,i)=>({id:`auxiliary-${i}`,title:`Synthetic auxiliary ${i}`,nodeIds:['left','right'],edgeIds:[edges[0].id],positions:{left:{x:0,y:0},right:{x:300,y:0}}}))],
 sources:[{id:'context-source',title:'Synthetic endpoint context',location:'Synthetic selected source:12; not a connection receipt'},{id:'private-source',title:relationshipPrivate,location:relationshipPrivate,visibility:'private'}]}));
}
async function relationshipDocument(page:Page){await page.getByRole('button',{name:'JSON / AI',exact:true}).click();const text=await page.getByLabel('Project JSON',{exact:true}).inputValue();const document=validateDocument(JSON.parse(text));expect(document.observations).toEqual([]);await page.getByRole('button',{name:'Close dialog',exact:true}).click();return text;}
async function importRelationships(page:Page,id:string){await page.goto('/');await page.getByRole('button',{name:'JSON / AI',exact:true}).click();await page.getByLabel('Project JSON',{exact:true}).fill(JSON.stringify(relationshipProject(id)));await page.getByRole('button',{name:'Validate JSON',exact:true}).click();await page.getByRole('button',{name:'Apply imported document',exact:true}).click();await expect(page.getByText('Saved locally',{exact:true})).toBeVisible();return relationshipDocument(page);}
const relationSheet=(page:Page)=>page.getByRole('region',{name:'Relationships output',exact:true});
const relationCount=(page:Page)=>relationSheet(page).getByRole('status',{name:'Connection table count',exact:true});

