 const before=await importRelationships(page,'synthetic-public-relations');await page.getByRole('button',{name:'Relationships',exact:true}).click();const sheet=relationSheet(page);await sheet.getByRole('button',{name:'Next connections',exact:true}).click();await expect(sheet).toContainText(relationshipPrivate);
