function sessionReturnProject(id:string){const p=relationshipProject(id),keep=new Set(['connection-00','connection-01','private-connection']);p.edges=p.edges.filter(e=>keep.has(e.id));p.edges.find(e=>e.id==='connection-01')!.source='parent';const root=p.views.find(v=>v.id==='root')!;root.positions.right.x=900;root.positions.private.x=1200;p.views.forEach(v=>{v.edgeIds=v.edgeIds.filter(id=>keep.has(id));});return validateDocument(p);}
async function importSessionReturnProject(page:Page,id:string){await page.goto('/');await page.getByRole('button',{name:'JSON / AI',exact:true}).click();await page.getByLabel('Project JSON',{exact:true}).fill(JSON.stringify(sessionReturnProject(id)));await page.getByRole('button',{name:'Validate JSON',exact:true}).click();await expect(page.getByRole('button',{name:'Apply imported document',exact:true})).toBeEnabled();await page.getByRole('button',{name:'Apply imported document',exact:true}).click();await expect(page.getByText('Saved locally',{exact:true})).toBeVisible();return relationshipDocument(page);}

async function storedReturnRow(page:Page,id:string){return page.evaluate(projectId=>new Promise<string>((resolve,reject)=>{
 const request=indexedDB.open('diagramcloud-v1',1);request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,read=db.transaction('projects','readonly').objectStore('projects').get(projectId);read.onerror=()=>{db.close();reject(read.error);};read.onsuccess=()=>{const value=JSON.stringify(read.result??null);db.close();resolve(value);};};
}),id);}
const returnEdge=(page:Page,id:string)=>page.getByTestId('view-root').locator(`.react-flow__edge[data-id="${id}"]`);
async function selectReturnEdge(page:Page,id:string){
 await page.getByTestId('view-root').locator('.canvas-frame').evaluate(element=>element.scrollIntoView({block:'center'}));
 const point=await returnEdge(page,id).locator('.react-flow__edge-interaction').evaluate((element,edgeId)=>{
  const path=element as SVGPathElement,matrix=path.getScreenCTM();if(!matrix)return null;
  for(const fraction of [.5,.4,.6,.25,.75]){const point=path.getPointAtLength(path.getTotalLength()*fraction).matrixTransform(matrix);
   if(document.elementFromPoint(point.x,point.y)?.closest('.react-flow__edge')?.getAttribute('data-id')===edgeId)return {x:point.x,y:point.y};
  }return null;
 },id);
 expect(point,'The intended connection must have a visible, unobstructed pointer target').not.toBeNull();
 await page.mouse.click(point!.x,point!.y);
}
const connectionEditor=(page:Page)=>page.locator('.inspector').filter({hasText:'CONNECTION EDITOR'});

test('session return restores exact edge and output sheet while parent truncation Pin source and persisted Project stay independent',async({page},info)=>{
 const id='synthetic-semantic-session-return',before=await importSessionReturnProject(page,id);await page.getByRole('tab',{name:'Edit',exact:true}).click();
 const rowBefore=await storedReturnRow(page,id),preferences=await page.evaluate(()=>Object.keys(localStorage).sort().map(key=>[key,localStorage.getItem(key)]));
 const root=page.getByTestId('view-root'),child=page.getByTestId('view-child');await root.getByRole('button',{name:'Explore Synthetic relation parent',exact:true}).click();await expect(child).toBeVisible();
 await page.getByRole('button',{name:'Details panel',exact:true}).click();const context=page.getByTestId('project-context');await context.getByRole('button',{name:'Pin context',exact:true}).click();
 // A new selection in root still truncates its child; history may restore the earlier valid parent+child entry.
 await root.getByRole('button',{name:'Explore Synthetic endpoint B',exact:true}).click();await expect(child).toHaveCount(0);await page.getByRole('button',{name:'Back',exact:true}).click();await expect(root).toBeVisible();await expect(child).toBeVisible();await expect(context).toContainText('Active selection: Synthetic relation parent');
 await child.getByRole('button',{name:'Explore Synthetic endpoint B',exact:true}).click();await expect(page.locator('.breadcrumb').getByRole('button',{name:'Synthetic retained detail',exact:true})).toBeVisible();
 // Child selection can scroll the parent beneath the fixed header: target its actual visible stroke.
 await selectReturnEdge(page,'connection-00');await expect(connectionEditor(page).getByRole('heading',{name:'Synthetic connection 0',exact:true})).toBeVisible();
 await selectReturnEdge(page,'connection-01');await expect(connectionEditor(page).getByRole('heading',{name:'Synthetic connection 1',exact:true})).toBeVisible();
 await page.getByRole('button',{name:'Back',exact:true}).click();await expect(connectionEditor(page).getByRole('heading',{name:'Synthetic connection 0',exact:true})).toBeVisible();await expect(returnEdge(page,'connection-00').locator('.edge-selected')).toHaveCount(1);
 await page.getByRole('button',{name:'Forward',exact:true}).click();await expect(connectionEditor(page).getByRole('heading',{name:'Synthetic connection 1',exact:true})).toBeVisible();await expect(child).toBeVisible();
 await page.getByRole('button',{name:'Relationships',exact:true}).click();await expect(relationSheet(page)).toBeVisible();await page.getByRole('button',{name:'Back',exact:true}).click();await expect(root).toBeVisible();await expect(child).toBeVisible();await expect(connectionEditor(page).getByRole('heading',{name:'Synthetic connection 1',exact:true})).toBeVisible();
 await page.getByRole('button',{name:'Forward',exact:true}).click();await expect(relationSheet(page)).toBeVisible();await expect(context).toContainText('Pinned scope: Synthetic relation parent');await expect(context).toContainText('Content uses current document revision');
 expect(await relationshipDocument(page)).toBe(before);expect(await storedReturnRow(page,id)).toBe(rowBefore);expect(await page.evaluate(()=>Object.keys(localStorage).sort().map(key=>[key,localStorage.getItem(key)]))).toEqual(preferences);
 await page.setViewportSize({width:390,height:844});const back=page.getByRole('button',{name:'Back',exact:true});await back.focus();await page.keyboard.press('Enter');await expect(root).toBeVisible();await expect(child).toBeVisible();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:info.outputPath('semantic-return-edge-parent-pin-390.png')});expect(await relationshipDocument(page)).toBe(before);
});

test('deleted target is refused generically then pruned without undoing the authored deletion or retargeting another membership',async({page})=>{
 const id='synthetic-return-deleted',before=await importSessionReturnProject(page,id);await page.getByRole('tab',{name:'Edit',exact:true}).click();const root=page.getByTestId('view-root'),child=page.getByTestId('view-child');await root.getByRole('button',{name:'Explore Synthetic relation parent',exact:true}).click();await expect(child).toBeVisible();
 await child.getByRole('button',{name:'Explore Synthetic endpoint B',exact:true}).click();await child.getByRole('button',{name:'Explore Synthetic retained code',exact:true}).click();await child.getByRole('button',{name:'Explore Synthetic endpoint B',exact:true}).click();await page.getByRole('button',{name:'Delete component',exact:true}).click();await expect(page.getByText('Saved locally',{exact:true})).toBeVisible();
 const deleted=await relationshipDocument(page),rowDeleted=await storedReturnRow(page,id);expect(deleted).not.toBe(before);expect(JSON.parse(deleted).nodes.some((n:{id:string})=>n.id==='right')).toBe(false);
 await page.getByRole('button',{name:'Back',exact:true}).click();const notice=page.getByRole('status').filter({hasText:'This navigation target is unavailable in the current permitted context.'});await expect(notice).toBeVisible();await expect(notice).not.toContainText('Synthetic endpoint B');await expect(child).toBeVisible();await expect(page.getByRole('button',{name:'Explore Synthetic endpoint B',exact:true})).toHaveCount(0);expect(await relationshipDocument(page)).toBe(deleted);
 await page.getByRole('button',{name:'Back',exact:true}).click();await expect(page.getByRole('heading',{name:'Synthetic retained code',exact:true}).first()).toBeVisible();await expect(root).toBeVisible();await expect(child).toBeVisible();expect(await relationshipDocument(page)).toBe(deleted);expect(await storedReturnRow(page,id)).toBe(rowDeleted);
});

test('public and project boundaries cannot replay old private session entries or restore a revoked Pin',async({page})=>{
 const id='synthetic-return-scope',before=await importSessionReturnProject(page,id);await page.getByRole('tab',{name:'Edit',exact:true}).click();const root=page.getByTestId('view-root');await root.getByRole('button',{name:`Explore ${relationshipPrivate}`,exact:true}).click();await page.getByRole('button',{name:'Details panel',exact:true}).click();const context=page.getByTestId('project-context');await context.getByRole('button',{name:'Pin context',exact:true}).click();await expect(context).toContainText('Pinned scope: '+relationshipPrivate);await root.getByRole('button',{name:'Explore Synthetic endpoint B',exact:true}).click();await expect(page.getByRole('button',{name:'Back',exact:true})).toBeEnabled();
 for(const mode of ['Portfolio','Present'] as const){
  await page.getByRole('tab',{name:mode,exact:true}).click();await expect(page.getByRole('button',{name:'Back',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Forward',exact:true})).toBeDisabled();await expect(page.locator('body')).not.toContainText(relationshipPrivate);await expect(context).toContainText('Pinned context unavailable in the current permitted scope.');await page.getByRole('tab',{name:'Edit',exact:true}).click();await expect(page.getByRole('button',{name:'Back',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Forward',exact:true})).toBeDisabled();await expect(context).toContainText('Pinned context unavailable in the current permitted scope.');
 }
 expect(await relationshipDocument(page)).toBe(before);const stored=await storedReturnRow(page,id);
 const next=sessionReturnProject('synthetic-return-next-project');await page.getByRole('button',{name:'JSON / AI',exact:true}).click();await page.getByLabel('Project JSON',{exact:true}).fill(JSON.stringify(next));await page.getByRole('button',{name:'Validate JSON',exact:true}).click();await expect(page.getByRole('button',{name:'Apply imported document',exact:true})).toBeEnabled();await page.getByRole('button',{name:'Apply imported document',exact:true}).click();await expect(page.getByText('Saved locally',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Back',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Forward',exact:true})).toBeDisabled();expect(await storedReturnRow(page,id)).toBe(stored);
});


// Canonical view text remains distinct from transient session return and browser-local panels.
function viewTextProject(id:string){return validateDocument(documentSchema.parse({schemaVersion:1,id,revision:5,title:'Synthetic view text '+id,rootViewId:'root',
 nodes:[{id:'parent',label:'Synthetic public portal',childViewId:'child',sourceIds:['context-source']},{id:'inner',label:'Synthetic inner component',blockIds:['explanation'],sourceIds:['context-source']},{id:'private-parent',label:'SYNTHETIC_VIEW_PRIVATE_PORTAL',childViewId:'private-view',visibility:'private'},{id:'private-leaf',label:'SYNTHETIC_VIEW_PRIVATE_LEAF',visibility:'private'}],
 edges:[],views:[{id:'root',title:'Synthetic original root',description:'Original authored boundary.',nodeIds:['parent','private-parent'],positions:{parent:{x:0,y:0},'private-parent':{x:360,y:0}},perspective:'system',design:{type:'auto',focal:['parent']}},{id:'child',title:'Synthetic original child',description:'Original authored detail.',nodeIds:['inner'],positions:{inner:{x:0,y:0}},perspective:'cicd'},{id:'private-view',title:'SYNTHETIC_VIEW_PRIVATE_TITLE',description:'SYNTHETIC_VIEW_PRIVATE_DESCRIPTION',visibility:'private',nodeIds:['private-leaf'],positions:{'private-leaf':{x:0,y:0}}}],
 blocks:[{id:'explanation',title:'Synthetic retained explanation',type:'text',text:'Authored example only; no execution is evidenced.',provenance:'synthetic',sourceIds:['context-source']}],sources:[{id:'context-source',title:'Synthetic view context',location:'Synthetic browser fixture, not an execution receipt'}]}));}
async function importViewText(page:Page,input:ReturnType<typeof viewTextProject>){
 await page.getByRole('button',{name:'JSON / AI',exact:true}).click();await page.getByLabel('Project JSON',{exact:true}).fill(JSON.stringify(input));await page.getByRole('button',{name:'Validate JSON',exact:true}).click();await expect(page.getByRole('button',{name:'Apply imported document',exact:true})).toBeEnabled();await page.getByRole('button',{name:'Apply imported document',exact:true}).click();await expect(page.getByText('Saved locally',{exact:true})).toBeVisible();
}
async function openViewText(page:Page,id:string){await page.goto('/');const input=viewTextProject(id);await importViewText(page,input);await page.getByRole('tab',{name:'Edit',exact:true}).click();const before=validateDocument(JSON.parse(await relationshipDocument(page)));await expect.poll(async()=>{const row=JSON.parse(await storedReturnRow(page,id));return row?.json?JSON.parse(row.json):null;}).toEqual(before);return before;}
const viewTextForm=(page:Page,id='root')=>page.getByTestId('view-'+id).getByRole('form',{name:'Edit view details',exact:true});
async function beginViewText(page:Page,id='root'){await page.getByTestId('view-'+id).getByRole('button',{name:'Edit view details',exact:true}).click();const form=viewTextForm(page,id);await expect(form).toBeVisible();return form;}
async function waitViewTextSave(page:Page,input:ReturnType<typeof viewTextProject>){await expect.poll(async()=>{const row=JSON.parse(await storedReturnRow(page,input.id));return row?.json?JSON.parse(row.json):null;}).toEqual(input);await expect(page.getByText('Saved locally',{exact:true})).toBeVisible();}
function changedViewText(input:ReturnType<typeof viewTextProject>,viewId:string,title:string,description:string){const next=structuredClone(input);next.revision++;const view=next.views.find(view=>view.id===viewId)!;view.title=title;view.description=description;return next;}
async function downloadViewText(page:Page,kind:'authoring'|'public'){
 await page.getByRole('button',{name:'Export & share',exact:true}).click();const pending=page.waitForEvent('download');await page.getByRole('button',{name:kind==='authoring'?/^Authoring JSON/:/^Public JSON/}).click();const file=await pending,location=await file.path();expect(location).not.toBeNull();const value=validateDocument(JSON.parse(readFileSync(location!,'utf8')));await page.getByRole('button',{name:'Close dialog',exact:true}).click();return value;
}

test('view text cancel validation one Undo and durable backup preserve every unrelated canonical field',async({page})=>{
 const before=await openViewText(page,'synthetic-view-text-durable'),root=page.getByTestId('view-root'),stored=await storedReturnRow(page,before.id);
 let form=await beginViewText(page);await form.getByLabel('View title',{exact:true}).fill('Uncommitted local draft');await form.getByRole('button',{name:'Cancel view edit',exact:true}).click();expect(await storedReturnRow(page,before.id)).toBe(stored);expect(JSON.parse(await relationshipDocument(page))).toEqual(before);
 for(const invalid of [{title:'',description:''},{title:'   ',description:''},{title:'x'.repeat(161),description:''},{title:'Valid draft title',description:'x'.repeat(2001)}]){
  form=await beginViewText(page);await form.getByLabel('View title',{exact:true}).fill(invalid.title);await form.getByLabel('View description',{exact:true}).fill(invalid.description);await form.getByRole('button',{name:'Apply view details',exact:true}).click();await expect(root.getByRole('alert')).toContainText('Enter a nonblank title of 1–160 characters');await expect(form).toBeVisible();expect(await storedReturnRow(page,before.id)).toBe(stored);await form.getByRole('button',{name:'Cancel view edit',exact:true}).click();
 }
 form=await beginViewText(page);const title='  Synthetic authored root  ',description='Authored purpose <and> constraints; execution remains UNKNOWN.';await form.getByLabel('View title',{exact:true}).fill(title);await form.getByLabel('View description',{exact:true}).fill(description);await form.getByRole('button',{name:'Apply view details',exact:true}).click();
 const expected=changedViewText(before,'root',title,description);await waitViewTextSave(page,expected);expect(JSON.parse(await relationshipDocument(page))).toEqual(expected);await expect(root.locator('.view-heading h2')).toContainText('Synthetic authored root');await page.locator('.side-tabs').getByRole('button',{name:'Navigate',exact:true}).click();const navigator=page.getByTestId('project-navigator');await navigator.getByRole('tab',{name:'Views',exact:true}).click();await expect(navigator.getByRole('button',{name:'Synthetic authored root',exact:true})).toBeVisible();await expect(navigator).toContainText(description);
 await page.getByRole('button',{name:'Undo',exact:true}).click();await waitViewTextSave(page,before);expect(JSON.parse(await relationshipDocument(page))).toEqual(before);await page.getByRole('button',{name:'Redo',exact:true}).click();await waitViewTextSave(page,expected);expect(JSON.parse(await relationshipDocument(page))).toEqual(expected);
 const noOpRow=await storedReturnRow(page,before.id);form=await beginViewText(page);await form.getByRole('button',{name:'Apply view details',exact:true}).click();expect(await storedReturnRow(page,before.id)).toBe(noOpRow);expect(JSON.parse(await relationshipDocument(page))).toEqual(expected);
 expect(await downloadViewText(page,'authoring')).toEqual(expected);await page.reload();await page.locator('.project-card').filter({hasText:before.title}).click();await page.getByRole('tab',{name:'Edit',exact:true}).click();await expect(root.locator('.view-heading h2')).toContainText('Synthetic authored root');expect(JSON.parse(await relationshipDocument(page))).toEqual(expected);
 // Ordinary reviewed backup import retains the exact authored view records and all non-revision facts.
 await importViewText(page,expected);const restored=JSON.parse(await relationshipDocument(page));expect({...restored,revision:expected.revision}).toEqual(expected);
});

