 expect(await form.evaluate(element=>element.scrollWidth<=element.clientWidth)).toBe(true);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await form.screenshot({path:info.outputPath('view-text-editor-390.png')});await page.keyboard.press('Tab');await expect(form.getByRole('button',{name:'Apply view details',exact:true})).toBeFocused();await page.keyboard.press('Enter');await expect(opener).toBeFocused();
 const expected=changedViewText(before,'child','Synthetic authored child','A stated author purpose; no status or runtime claim.');await waitViewTextSave(page,expected);await expect(root).toBeVisible();await expect(child.locator('.view-heading h2')).toHaveText('Synthetic authored child');await expect(context).toContainText('Pinned scope: Synthetic public portal');expect(JSON.parse(await relationshipDocument(page))).toEqual(expected);
 const saved=await storedReturnRow(page,before.id);await opener.focus();await page.keyboard.press('Enter');await form.getByLabel('View title',{exact:true}).fill('Escape must not save');await page.keyboard.press('Escape');await expect(form).toHaveCount(0);await expect(opener).toBeFocused();expect(await storedReturnRow(page,before.id)).toBe(saved);
 await child.locator('.canvas-frame').evaluate(element=>element.scrollIntoView({block:'center'}));await child.getByRole('button',{name:'Explore Synthetic inner component',exact:true}).focus();await page.keyboard.press('Enter');await page.getByRole('button',{name:'Back',exact:true}).click();await expect(root).toBeVisible();await expect(child.locator('.view-heading h2')).toHaveText('Synthetic authored child');expect(JSON.parse(await relationshipDocument(page))).toEqual(expected);expect(await page.evaluate(()=>Object.keys(localStorage).sort().map(key=>[key,localStorage.getItem(key)]))).toEqual(preferences);await child.screenshot({path:info.outputPath('view-text-child-retained-390.png')});
