function readonlyConnectionProject(id:string){
 const p=sessionReturnProject(id);p.title='Synthetic read-only connection inspection';
 const child=p.views.find(view=>view.id==='child')!;child.positions.right={x:700,y:0};child.edgeIds=['child-only'];
 p.edges.push({id:'child-only',source:'code',target:'right',label:'Synthetic child-only relation',kind:'dependency',speed:'fast',basis:'unknown',visibility:'public'});
 p.edges.push({id:'unplaced-connection',source:'left',target:'right',label:'Synthetic unplaced relation',kind:'query',speed:'medium',basis:'planned',visibility:'public'});
 const hidden=p.edges.find(edge=>edge.id==='private-connection')!;hidden.quantity={value:17,unit:'private-unit',provenance:'author',note:relationshipPrivate};
 return validateDocument(p);
}
