 for(const kind of ['story','focal','child'] as const){const input=membershipRemovalProject('synthetic-view-removal-'+kind),right=input.views.find(view=>view.id==='right')!;if(kind==='story')input.story.push({...input.story[0],viewId:'right'});if(kind==='focal')right.design={type:'auto',focal:['shared']};validateDocument(input);const before=await openRemovalProject(page,input);await openRightMembership(page);const row=await storedReturnRow(page,before.id),view=kind==='child'?'root':'right',node=kind==='child'?'right-portal':'shared',form=await chooseViewRemoval(page,node,view);await expect(page.getByTestId('view-'+view).getByRole('alert')).toContainText('This component cannot be removed from this view.');await expect(form.getByRole('region',{name:'View removal impact review',exact:true})).toHaveCount(0);await form.getByRole('button',{name:'Cancel view removal',exact:true}).click();expect(await removalDocument(page)).toEqual(before);expect(await storedReturnRow(page,before.id)).toBe(row);}
