test('view removal reviews are revoked by Undo modal mode and same-ID replacement while fresh native authoring still works',async({page})=>{
 const before=await openRemovalProject(page,membershipRemovalProject('synthetic-view-removal-stale'));await openRightMembership(page);let form=await chooseViewRemoval(page,'shared');await page.keyboard.press('Escape');await expect(form).toHaveCount(0);await expect(page.getByTestId('view-right').getByRole('button',{name:'Remove from this view',exact:true})).toBeFocused();expect(await removalDocument(page)).toEqual(before);
 for(const mode of ['Explore','Portfolio','Present'] as const){form=await chooseViewRemoval(page,'shared');await page.getByRole('tab',{name:mode,exact:true}).click();await expect(page.getByRole('button',{name:'Remove from this view',exact:true})).toHaveCount(0);await page.getByRole('tab',{name:'Edit',exact:true}).click();await expect(removalForm(page)).toHaveCount(0);expect(await removalDocument(page)).toEqual(before);await openRightMembership(page);}
 form=await chooseViewRemoval(page,'shared');await page.getByRole('button',{name:'JSON / AI',exact:true}).click();await expect(form).toHaveCount(0);await page.getByRole('button',{name:'Close dialog',exact:true}).click();await expect(removalForm(page)).toHaveCount(0);
 // Make an ordinary parent membership edit, then Undo while a new removal review is open.
 const added=await applyMembership(page,before,'root','shared');form=await chooseViewRemoval(page,'shared');await page.getByRole('button',{name:'Undo',exact:true}).click();await expect(form).toHaveCount(0);await waitViewTextSave(page,before);await page.getByRole('button',{name:'Redo',exact:true}).click();await waitViewTextSave(page,added);
 form=await chooseViewRemoval(page,'shared');const replacement=structuredClone(added);replacement.nodes.find(node=>node.id==='shared')!.summary='Current replacement authored explanation';await importViewText(page,replacement);await page.getByRole('tab',{name:'Edit',exact:true}).click();await expect(page.getByRole('form',{name:'Remove component from this view',exact:true})).toHaveCount(0);const current=await removalDocument(page);expect(current.nodes.find(node=>node.id==='shared')!.summary).toBe('Current replacement authored explanation');await openRightMembership(page);form=await chooseViewRemoval(page,'shared');await form.getByRole('button',{name:'Apply view removal',exact:true}).click();await waitViewTextSave(page,expectedViewRemoval(current,'right','shared'));
});

test('private one-view removal keeps public outputs honest and native review controls fit390px without adding readonly SDK authoring',async({page},info)=>{
 const input=membershipRemovalProject('synthetic-view-removal-public');input.views.find(view=>view.id==='right')!.title='R'.repeat(160);input.nodes.find(node=>node.id==='shared')!.label='S'.repeat(160);validateDocument(input);const before=await openRemovalProject(page,input),publicBefore=await downloadViewText(page,'public');await openRightMembership(page);let form=await chooseViewRemoval(page,'private-leaf');await form.getByRole('button',{name:'Apply view removal',exact:true}).click();const after=expectedViewRemoval(before,'right','private-leaf');await waitViewTextSave(page,after);const publicAfter=await downloadViewText(page,'public');expect({...publicAfter,revision:publicBefore.revision}).toEqual(publicBefore);expect(JSON.stringify(publicAfter)).not.toContain('SYNTHETIC_MEMBERSHIP_PRIVATE');expect(after.nodes).toEqual(before.nodes);expect(after.edges).toEqual(before.edges);expect(after.sources).toEqual(before.sources);
 await page.setViewportSize({width:390,height:844});form=await chooseViewRemoval(page,'shared');const review=form.getByRole('region',{name:'View removal impact review',exact:true});await review.scrollIntoViewIfNeeded();await expect(review).toContainText('R'.repeat(160));await expect(review).toContainText('S'.repeat(160));expect(await form.evaluate(element=>element.scrollWidth<=element.clientWidth)).toBe(true);expect(await review.evaluate(element=>element.scrollWidth<=element.clientWidth)).toBe(true);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await review.screenshot({path:info.outputPath('view-removal-review-390.png')});await form.getByRole('button',{name:'Cancel view removal',exact:true}).focus();await page.keyboard.press('Enter');await expect(form).toHaveCount(0);expect(await removalDocument(page)).toEqual(after);
 for(const mode of ['Explore','Portfolio','Present'] as const){await page.getByRole('tab',{name:mode,exact:true}).click();await expect(page.getByRole('button',{name:'Remove from this view',exact:true})).toHaveCount(0);if(mode!=='Explore')await expect(page.locator('body')).not.toContainText('SYNTHETIC_MEMBERSHIP_PRIVATE');}await page.screenshot({path:info.outputPath('view-removal-public-boundary-390.png')});
 await page.goto(reactViewerUrl);await expect(page.getByRole('region',{name:'Viewer A',exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Remove from this view',exact:true})).toHaveCount(0);
});

